-- PREPARED CONTRACT ONLY. DO NOT APPLY FROM THIS CHECKPOINT.
-- Requires existing assessment, consultation, appointment, document, consent, prescription, order, communication and service-record contracts.
-- Appointments are included only through explicit care_assessment_links; names, titles and temporal proximity never create a client relation.
begin;
create schema if not exists care_private;
create table if not exists public.counseling_coordination_paths(
 id uuid primary key,tenant_id uuid not null references public.tenants(id),client_id uuid not null references public.clients(id),assessment_id uuid not null references public.care_assessments(id) on delete restrict,
 root_id uuid not null,previous_id uuid references public.counseling_coordination_paths(id) on delete restrict,revision integer not null check(revision>0),status text not null check(status in('draft','review_requested','returned','released','corrected')),
 entry jsonb not null,reason text not null default '',recorded_by uuid not null references public.profiles(id),recorded_at timestamptz not null default clock_timestamp(),fingerprint text not null,unique(root_id,revision)
);
create index if not exists counseling_coordination_path_page on public.counseling_coordination_paths(tenant_id,client_id,assessment_id,recorded_at desc,id desc);
create table if not exists care_private.counseling_coordination_receipts(tenant_id uuid not null,request_id uuid not null,client_id uuid not null,assessment_id uuid not null,actor_id uuid not null,packet jsonb not null,path_id uuid not null references public.counseling_coordination_paths(id),created_at timestamptz not null default clock_timestamp(),primary key(tenant_id,request_id));
create or replace function care_private.reject_counseling_coordination_change() returns trigger language plpgsql security definer set search_path='' as $$begin raise exception 'Beratungs-, Koordinations- und Quittungsoriginale sind append-only.' using errcode='42501';end$$;
revoke all on function care_private.reject_counseling_coordination_change() from public,anon,authenticated;
drop trigger if exists protect_counseling_coordination_original on public.counseling_coordination_paths;create trigger protect_counseling_coordination_original before update or delete on public.counseling_coordination_paths for each row execute function care_private.reject_counseling_coordination_change();
drop trigger if exists protect_counseling_coordination_receipt on care_private.counseling_coordination_receipts;create trigger protect_counseling_coordination_receipt before update or delete on care_private.counseling_coordination_receipts for each row execute function care_private.reject_counseling_coordination_change();
alter table public.counseling_coordination_paths enable row level security;alter table care_private.counseling_coordination_receipts enable row level security;
revoke all on public.counseling_coordination_paths,care_private.counseling_coordination_receipts from public,anon,authenticated;grant select on public.counseling_coordination_paths to authenticated;
drop policy if exists counseling_coordination_read on public.counseling_coordination_paths;create policy counseling_coordination_read on public.counseling_coordination_paths for select to authenticated using(tenant_id=public.current_tenant_id() and public.is_active_pfleger_client(client_id) and public.has_permission('pflege.plans.view') and public.has_permission('beratung.cases.view') and public.has_permission('office.appointments.view') and public.has_permission('office.documents.view') and public.has_permission('communication.view_center') and public.has_permission('communication.view_client_threads') and public.has_permission('office.clients.view_sensitive'));

create or replace function care_private.assert_counseling_coordination_actor(p_tenant uuid,p_actor uuid,p_manage boolean default false,p_release boolean default false) returns void language plpgsql security definer set search_path='' as $$begin
 if auth.uid() is null or p_tenant is distinct from public.current_tenant_id() or p_actor is distinct from public.resolve_current_profile_id() or not exists(select 1 from public.profiles p where p.id=p_actor and p.tenant_id=p_tenant and p.is_active)
 or public.has_permission('pflege.plans.view') is not true or public.has_permission('beratung.cases.view') is not true or public.has_permission('office.appointments.view') is not true or public.has_permission('office.documents.view') is not true or public.has_permission('communication.view_center') is not true or public.has_permission('communication.view_client_threads') is not true or public.has_permission('office.clients.view_sensitive') is not true
 or (p_manage and (public.has_permission('pflege.assessments.manage') is not true or public.has_permission('pflege.orders.manage') is not true)) or (p_release and public.has_permission('pflege.audit.view') is not true)
 then raise exception 'Aktuelle Sitzung, Person, Mandant oder Beratungs-/Koordinationsrecht fehlt.' using errcode='42501';end if;
end$$;
revoke all on function care_private.assert_counseling_coordination_actor(uuid,uuid,boolean,boolean) from public,anon,authenticated;
create or replace function care_private.counseling_coordination_ref(p_id uuid,p_revision integer,p_recorded timestamptz,p_tenant uuid,p_client uuid,p_assessment uuid,p_payload jsonb) returns jsonb language sql immutable strict set search_path='' as $$select jsonb_build_object('id',p_id,'revision',p_revision,'recordedAt',to_char(p_recorded at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'fingerprint','sha256:'||encode(extensions.digest(convert_to(p_payload::text,'UTF8'),'sha256'),'hex'),'tenantId',p_tenant,'clientId',p_client,'assessmentId',p_assessment,'payload',p_payload)$$;
revoke all on function care_private.counseling_coordination_ref(uuid,integer,timestamptz,uuid,uuid,uuid,jsonb) from public,anon,authenticated;
create or replace function care_private.counseling_coordination_original(p_path uuid) returns jsonb language sql security definer set search_path='' stable as $$with head as(select * from public.counseling_coordination_paths where id=p_path),history as(select h.* from public.counseling_coordination_paths h join head x on x.root_id=h.root_id where h.revision<=x.revision order by h.revision),items as(select jsonb_agg(jsonb_build_object('id',id,'revision',revision,'previousId',previous_id,'recordedAt',to_char(recorded_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'recordedBy',recorded_by,'reason',reason,'status',status,'entry',entry,'fingerprint',fingerprint) order by revision) value from history) select jsonb_build_object('id',h.id,'tenantId',h.tenant_id,'clientId',h.client_id,'assessmentId',h.assessment_id,'rootId',h.root_id,'headId',h.id,'revision',h.revision,'status',h.status,'entry',h.entry,'history',i.value) from head h cross join items i$$;
revoke all on function care_private.counseling_coordination_original(uuid) from public,anon,authenticated;

create or replace function care_private.read_counseling_coordination_context(p_tenant_id uuid,p_client_id uuid,p_assessment_id uuid,p_actor_profile_id uuid) returns jsonb language plpgsql security definer set search_path='' stable as $$declare a public.care_assessments%rowtype;result jsonb;begin
 perform care_private.assert_counseling_coordination_actor(p_tenant_id,p_actor_profile_id,false,false);select * into a from public.care_assessments x where x.id=p_assessment_id and x.tenant_id=p_tenant_id and x.subject_type='client' and x.subject_id=p_client_id;
 if a.id is null or public.is_active_pfleger_client(p_client_id) is not true then raise exception 'Eigenes Assessment oder aktiver Pflegefall fehlt.' using errcode='42501';end if;
 select jsonb_build_object(
 'assessment',jsonb_build_array(care_private.counseling_coordination_ref(a.id,coalesce(a.draft_revision,0),a.updated_at,p_tenant_id,p_client_id,a.id,to_jsonb(a)-'tenant_id')),
 'appointments',coalesce((select jsonb_agg(care_private.counseling_coordination_ref(x.id,0,x.updated_at,p_tenant_id,p_client_id,a.id,jsonb_build_object('title',x.title,'starts_at',x.starts_at,'ends_at',x.ends_at,'status',x.status,'location',x.location,'explicit_assessment_link',l.id)) order by x.id) from public.care_assessment_links l join public.appointments x on x.id=l.entity_id and x.tenant_id=l.tenant_id where l.tenant_id=p_tenant_id and l.assessment_id=a.id and l.entity_type='appointment' and l.relation in('consultation_appointment','therapy_appointment')),'[]'::jsonb),
 'consultations',coalesce((select jsonb_agg(care_private.counseling_coordination_ref(s.id,0,s.updated_at,p_tenant_id,p_client_id,a.id,jsonb_build_object('case_id',s.case_id,'session_at',s.session_at,'duration_minutes',s.duration_minutes,'occasion_key',s.occasion_key,'status',s.status)) order by s.id) from public.consultation_sessions s join public.consultation_cases_v2 c on c.id=s.case_id and c.tenant_id=s.tenant_id where s.tenant_id=p_tenant_id and c.client_id=p_client_id),'[]'::jsonb),
 'documents',coalesce((select jsonb_agg(care_private.counseling_coordination_ref(d.id,0,d.updated_at,p_tenant_id,p_client_id,a.id,jsonb_build_object('title',d.title,'file_name',d.file_name,'category',d.category,'status',d.status,'sensitivity',d.sensitivity,'valid_until',d.valid_until)) order by d.id) from public.client_documents d where d.tenant_id=p_tenant_id and d.client_id=p_client_id),'[]'::jsonb),
 'contacts',coalesce((select jsonb_agg(care_private.counseling_coordination_ref(c.id,0,coalesce(c.updated_at,c.created_at),p_tenant_id,p_client_id,a.id,jsonb_build_object('name',c.name,'relationship',c.relationship,'first_name',c.first_name,'last_name',c.last_name,'notes',c.notes)) order by c.id) from public.client_contacts c where c.tenant_id=p_tenant_id and c.client_id=p_client_id),'[]'::jsonb),
 'people',coalesce((select jsonb_agg(care_private.counseling_coordination_ref(p.id,0,coalesce(p.updated_at,p.created_at),p_tenant_id,p_client_id,a.id,jsonb_build_object('display_name',coalesce(nullif(p.display_name,''),p.email),'active',p.is_active)) order by p.id) from public.profiles p where p.tenant_id=p_tenant_id and p.is_active),'[]'::jsonb),
 'prescriptions',coalesce((select jsonb_agg(care_private.counseling_coordination_ref(p.id,0,p.updated_at,p_tenant_id,p_client_id,a.id,to_jsonb(p)-'tenant_id'-'client_id') order by p.id) from public.client_prescriptions p where p.tenant_id=p_tenant_id and p.client_id=p_client_id),'[]'::jsonb),
 'orders',coalesce((select jsonb_agg(care_private.counseling_coordination_ref(o.id,0,o.updated_at,p_tenant_id,p_client_id,a.id,to_jsonb(o)-'tenant_id'-'client_id') order by o.id) from public.care_medical_orders o where o.tenant_id=p_tenant_id and o.client_id=p_client_id),'[]'::jsonb),
 'careLevels',coalesce((select jsonb_agg(care_private.counseling_coordination_ref(c.id,0,c.updated_at,p_tenant_id,p_client_id,a.id,to_jsonb(c)-'tenant_id'-'client_id') order by c.id) from public.client_care_levels c where c.tenant_id=p_tenant_id and c.client_id=p_client_id),'[]'::jsonb),
 'consents',coalesce((select jsonb_agg(care_private.counseling_coordination_ref(c.id,0,c.updated_at,p_tenant_id,p_client_id,a.id,jsonb_build_object('title',c.title,'scope',c.scope,'consent_type',c.consent_type,'granted',c.granted,'granted_at',c.granted_at,'expires_at',c.expires_at,'document_id',c.document_id)) order by c.id) from public.client_consents c where c.tenant_id=p_tenant_id and c.client_id=p_client_id and c.granted and (c.expires_at is null or c.expires_at>clock_timestamp())),'[]'::jsonb),
 'communications',coalesce((select jsonb_agg(care_private.counseling_coordination_ref(t.id,0,t.updated_at,p_tenant_id,p_client_id,a.id,jsonb_build_object('title',t.title,'status',t.status,'subject',t.subject,'last_message_at',t.last_message_at,'last_message_id',t.last_message_id,'document_id',t.document_id,'is_internal_only',t.is_internal_only,'signed_order_not_inferred',true)) order by t.id) from public.communication_threads t where t.tenant_id=p_tenant_id and t.client_id=p_client_id and t.deleted_at is null),'[]'::jsonb),
 'tasks',coalesce((select jsonb_agg(care_private.counseling_coordination_ref(t.id,0,t.updated_at,p_tenant_id,p_client_id,a.id,to_jsonb(t)-'tenant_id'-'client_id') order by t.id) from public.client_tasks t where t.tenant_id=p_tenant_id and t.client_id=p_client_id),'[]'::jsonb),
 'serviceRecords',coalesce((select jsonb_agg(care_private.counseling_coordination_ref(s.id,0,s.updated_at,p_tenant_id,p_client_id,a.id,to_jsonb(s)-'tenant_id'-'client_id') order by s.id) from public.client_service_records s where s.tenant_id=p_tenant_id and s.client_id=p_client_id),'[]'::jsonb),
 'paths',coalesce((select jsonb_agg(care_private.counseling_coordination_ref(v.id,v.revision,v.recorded_at,p_tenant_id,p_client_id,a.id,jsonb_build_object('title',v.entry->>'title','status',v.status)) order by v.id) from public.counseling_coordination_paths v where v.tenant_id=p_tenant_id and v.client_id=p_client_id and v.assessment_id=a.id),'[]'::jsonb)) into result;return result;
end$$;
revoke all on function care_private.read_counseling_coordination_context(uuid,uuid,uuid,uuid) from public,anon,authenticated;
create or replace function public.web_read_counseling_coordination_path_context(p_tenant_id uuid,p_client_id uuid,p_assessment_id uuid,p_actor_profile_id uuid) returns jsonb language sql security invoker set search_path='' as $$select care_private.read_counseling_coordination_context(p_tenant_id,p_client_id,p_assessment_id,p_actor_profile_id)$$;
revoke all on function public.web_read_counseling_coordination_path_context(uuid,uuid,uuid,uuid) from public,anon;grant execute on function public.web_read_counseling_coordination_path_context(uuid,uuid,uuid,uuid) to authenticated;

create or replace function care_private.read_counseling_coordination_page(p_tenant_id uuid,p_client_id uuid,p_assessment_id uuid,p_actor_profile_id uuid,p_cursor_recorded_at timestamptz,p_cursor_id uuid,p_page_size integer) returns jsonb language plpgsql security definer set search_path='' stable as $$declare rows jsonb;last_at timestamptz;last_id uuid;begin perform care_private.assert_counseling_coordination_actor(p_tenant_id,p_actor_profile_id,false,false);if p_page_size not between 1 and 100 or public.is_active_pfleger_client(p_client_id) is not true then raise exception 'Ungültige Verlaufsauswahl.' using errcode='42501';end if;with heads as(select distinct on(root_id) * from public.counseling_coordination_paths where tenant_id=p_tenant_id and client_id=p_client_id and assessment_id=p_assessment_id order by root_id,revision desc),page as(select * from heads where p_cursor_recorded_at is null or (recorded_at,id)<(p_cursor_recorded_at,p_cursor_id) order by recorded_at desc,id desc limit p_page_size) select coalesce(jsonb_agg(care_private.counseling_coordination_original(id) order by recorded_at desc,id desc),'[]'::jsonb),(array_agg(recorded_at order by recorded_at desc,id desc))[count(*)],(array_agg(id order by recorded_at desc,id desc))[count(*)] into rows,last_at,last_id from page;return jsonb_build_object('rows',rows,'nextCursorRecordedAt',case when last_at is null then null else to_char(last_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') end,'nextCursorId',last_id);end$$;
revoke all on function care_private.read_counseling_coordination_page(uuid,uuid,uuid,uuid,timestamptz,uuid,integer) from public,anon,authenticated;
create or replace function public.web_read_counseling_coordination_path_page(p_tenant_id uuid,p_client_id uuid,p_assessment_id uuid,p_actor_profile_id uuid,p_cursor_recorded_at timestamptz,p_cursor_id uuid,p_page_size integer) returns jsonb language sql security invoker set search_path='' as $$select care_private.read_counseling_coordination_page(p_tenant_id,p_client_id,p_assessment_id,p_actor_profile_id,p_cursor_recorded_at,p_cursor_id,p_page_size)$$;
revoke all on function public.web_read_counseling_coordination_path_page(uuid,uuid,uuid,uuid,timestamptz,uuid,integer) from public,anon;grant execute on function public.web_read_counseling_coordination_path_page(uuid,uuid,uuid,uuid,timestamptz,uuid,integer) to authenticated;

create or replace function care_private.commit_counseling_coordination_packet(p_packet jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare tenant uuid:=(p_packet->>'tenantId')::uuid;client uuid:=(p_packet->>'clientId')::uuid;assessment uuid:=(p_packet->>'assessmentId')::uuid;actor uuid:=(p_packet->>'actorId')::uuid;request uuid:=(p_packet->>'requestId')::uuid;entry jsonb:=p_packet->'entry';state text:=entry->>'status';prior care_private.counseling_coordination_receipts%rowtype;head public.counseling_coordination_paths%rowtype;next_id uuid:=gen_random_uuid();next_root uuid;next_revision integer;fingerprint text;current_sources jsonb;release_action boolean:=state in('released','corrected');begin
 if jsonb_typeof(p_packet) is distinct from 'object' or length(p_packet::text)>3500000 or p_packet->>'schemaVersion'<>'1' or p_packet->>'action' not in('create','revise') then raise exception 'Ungültiges Beratungs- und Koordinations-Gesamtpaket.' using errcode='23514';end if;perform care_private.assert_counseling_coordination_actor(tenant,actor,true,release_action);perform pg_advisory_xact_lock(hashtextextended(tenant::text||':'||client::text||':'||assessment::text,0));
 if not exists(select 1 from public.care_assessments a where a.id=assessment and a.tenant_id=tenant and a.subject_type='client' and a.subject_id=client) or public.is_active_pfleger_client(client) is not true then raise exception 'Assessment oder Pflegefall ist nicht aktuell zugänglich.' using errcode='42501';end if;
 select * into prior from care_private.counseling_coordination_receipts r where r.tenant_id=tenant and r.request_id=request for update;if prior.request_id is not null then if prior.client_id<>client or prior.assessment_id<>assessment or prior.actor_id<>actor or prior.packet<>p_packet then raise exception 'Anfrageidentität wurde mit anderen Originalen verwendet.' using errcode='23514';end if;return jsonb_build_object('requestId',request,'packet',prior.packet,'original',care_private.counseling_coordination_original(prior.path_id));end if;
 if entry->>'tenantId' is distinct from tenant::text or entry->>'clientId' is distinct from client::text or entry->>'assessmentId' is distinct from assessment::text or state not in('draft','review_requested','returned','released','corrected') then raise exception 'Akte oder Status ist ungültig.' using errcode='23514';end if;
 if nullif(entry#>>'{consultation,appointmentId}','') is null or nullif(entry#>>'{consultation,scheduledAt}','') is null or nullif(entry#>>'{consultation,performedAt}','') is null or length(btrim(coalesce(entry#>>'{consultation,scheduleBoundary}','')))<8 then raise exception 'Beratung muss Plan und tatsächliche Durchführung getrennt binden.' using errcode='23514';end if;
 if nullif(entry#>>'{mandatoryVisit,sessionId}','') is null or nullif(entry#>>'{mandatoryVisit,documentId}','') is null or length(btrim(coalesce(entry#>>'{mandatoryVisit,formVersion}','')))<3 or nullif(entry#>>'{mandatoryVisit,confirmedAt}','') is null then raise exception 'Pflichtbesuch benötigt Sitzung, Formularfassung und Bestätigung.' using errcode='23514';end if;
 if nullif(entry#>>'{relativeInstruction,contactId}','') is null or length(btrim(coalesce(entry#>>'{relativeInstruction,topic}','')))<3 or length(btrim(coalesce(entry#>>'{relativeInstruction,demonstratedAction}','')))<3 or nullif(entry#>>'{relativeInstruction,demonstratedAt}','') is null or length(btrim(coalesce(entry#>>'{relativeInstruction,understanding}','')))<3 or length(btrim(coalesce(entry#>>'{relativeInstruction,independentPerformance}','')))<3 or length(btrim(coalesce(entry#>>'{relativeInstruction,limits}','')))<3 then raise exception 'Anleitung benötigt Bezugsperson, tatsächliche Demonstration, Verständnis, unabhängige Leistung und Grenzen.' using errcode='23514';end if;
 if nullif(entry#>>'{aidSupply,prescriptionId}','') is null or nullif(entry#>>'{aidSupply,orderId}','') is null or nullif(entry#>>'{aidSupply,supplierContactId}','') is null or nullif(entry#>>'{aidSupply,orderedAt}','') is null or nullif(entry#>>'{aidSupply,deliveredAt}','') is null or nullif(entry#>>'{aidSupply,instructedAt}','') is null then raise exception 'Hilfsmittel benötigt getrennte Verordnung, Bestellung, Lieferung und Einweisung.' using errcode='23514';end if;
 if nullif(entry#>>'{discharge,transferDocumentId}','') is null or nullif(entry#>>'{discharge,firstCareRecordId}','') is null or length(btrim(coalesce(entry#>>'{discharge,prescriptionGaps}','')))<3 or length(btrim(coalesce(entry#>>'{discharge,gapPlan}','')))<3 then raise exception 'Entlassmanagement benötigt Originale und sichtbaren Lückenplan.' using errcode='23514';end if;
 if nullif(entry#>>'{benefitChange,careLevelId}','') is null or nullif(entry#>>'{benefitChange,decisionDocumentId}','') is null or length(btrim(coalesce(entry#>>'{benefitChange,historicalBillingBoundary}','')))<8 then raise exception 'Leistungsänderung benötigt Bescheid und historische Abrechnungsgrenze.' using errcode='23514';end if;
 if nullif(entry#>>'{therapy,consentId}','') is null or length(btrim(coalesce(entry#>>'{therapy,approvedScope}','')))<3 or length(btrim(coalesce(entry#>>'{therapy,sharedFields}','')))<3 or length(btrim(coalesce(entry#>>'{therapy,minimumNecessaryReason}','')))<8 then raise exception 'Therapiekoordination benötigt aktive Einwilligungsquelle und minimalen Datenumfang.' using errcode='23514';end if;
 if entry#>>'{doctorCommunication,verificationState}'<>'unverified' or nullif(entry#>>'{doctorCommunication,communicationId}','') is null or nullif(entry#>>'{doctorCommunication,medicalOrderId}','') is null or nullif(entry#>>'{doctorCommunication,confirmationDocumentId}','') is null or length(btrim(coalesce(entry#>>'{doctorCommunication,verificationBoundary}','')))<8 then raise exception 'Arztkontakt, Anordnung und Bestätigung bleiben getrennt und ungeprüft.' using errcode='23514';end if;
 if state='review_requested' and ((entry#>>'{review,requestedBy}')::uuid<>actor or nullif(entry#>>'{review,requestedAt}','') is null) then raise exception 'Prüfanfrage benötigt aktuelle Person und Zeitpunkt.' using errcode='23514';end if;if state='released' and ((entry#>>'{review,releasedBy}')::uuid<>actor or nullif(entry#>>'{review,releasedAt}','') is null or entry#>>'{review,requestedBy}'=actor::text) then raise exception 'Freigabe benötigt getrennte zweite Person.' using errcode='23514';end if;
 if state='returned' and ((entry#>>'{review,returnedBy}')::uuid<>actor or nullif(entry#>>'{review,returnedAt}','') is null or length(btrim(coalesce(entry#>>'{review,returnReason}','')))<10) then raise exception 'Rückgabe benötigt aktuelle Person, Zeitpunkt und konkreten Grund.' using errcode='23514';end if;
 if state='corrected' and (nullif(entry#>>'{review,correctionTargetId}','') is null or length(btrim(coalesce(entry#>>'{review,correctionReason}','')))<10 or not exists(select 1 from public.counseling_coordination_paths v where v.id=(entry#>>'{review,correctionTargetId}')::uuid and v.tenant_id=tenant and v.client_id=client and v.assessment_id=assessment)) then raise exception 'Append-only-Korrektur benötigt historisches Ziel und konkreten Grund.' using errcode='23514';end if;
 current_sources:=care_private.read_counseling_coordination_context(tenant,client,assessment,actor);if current_sources is distinct from p_packet->'sources' then raise exception 'Originalquellen wurden verändert. Vollständig neu laden.' using errcode='40001';end if;
 if not exists(select 1 from jsonb_array_elements(current_sources->'appointments') x where x->>'id'=entry#>>'{consultation,appointmentId}') or not exists(select 1 from jsonb_array_elements(current_sources->'appointments') x where x->>'id'=entry#>>'{therapy,appointmentId}') then raise exception 'Termin ist nicht ausdrücklich mit diesem Assessment verknüpft.' using errcode='23514';end if;
 if not exists(select 1 from jsonb_array_elements(current_sources->'consents') x where x->>'id'=entry#>>'{therapy,consentId}') then raise exception 'Aktive Einwilligungsquelle fehlt.' using errcode='23514';end if;
 if not exists(select 1 from jsonb_array_elements(current_sources->'people') x where x->>'id'=entry#>>'{consultation,performedBy}') or not exists(select 1 from jsonb_array_elements(current_sources->'people') x where x->>'id'=entry#>>'{mandatoryVisit,confirmationBy}') or not exists(select 1 from jsonb_array_elements(current_sources->'people') x where x->>'id'=entry#>>'{aidSupply,instructedBy}') then raise exception 'Durchführung, Bestätigung oder Einweisung ist nicht an eine aktuelle eigene Person gebunden.' using errcode='23514';end if;
 if not exists(select 1 from jsonb_array_elements(current_sources->'consultations') x where x->>'id'=entry#>>'{mandatoryVisit,sessionId}') or not exists(select 1 from jsonb_array_elements(current_sources->'consultations') x where x->>'id'=entry#>>'{benefitChange,counselingSessionId}') then raise exception 'Ausgewählte Beratungssitzung fehlt im aktuellen Klientenbestand.' using errcode='23514';end if;
 if not exists(select 1 from jsonb_array_elements(current_sources->'documents') x where x->>'id'=entry#>>'{mandatoryVisit,documentId}') or not exists(select 1 from jsonb_array_elements(current_sources->'documents') x where x->>'id'=entry#>>'{discharge,transferDocumentId}') or not exists(select 1 from jsonb_array_elements(current_sources->'documents') x where x->>'id'=entry#>>'{benefitChange,decisionDocumentId}') or not exists(select 1 from jsonb_array_elements(current_sources->'documents') x where x->>'id'=entry#>>'{doctorCommunication,confirmationDocumentId}') then raise exception 'Ausgewähltes Formular, Übergabe-, Bescheid- oder Bestätigungsoriginal fehlt.' using errcode='23514';end if;
 if not exists(select 1 from jsonb_array_elements(current_sources->'contacts') x where x->>'id'=entry#>>'{relativeInstruction,contactId}') or not exists(select 1 from jsonb_array_elements(current_sources->'contacts') x where x->>'id'=entry#>>'{aidSupply,supplierContactId}') or not exists(select 1 from jsonb_array_elements(current_sources->'contacts') x where x->>'id'=entry#>>'{therapy,providerContactId}') then raise exception 'Bezugsperson, Lieferant oder Therapieanbieter fehlt im aktuellen Klientenbestand.' using errcode='23514';end if;
 if not exists(select 1 from jsonb_array_elements(current_sources->'prescriptions') x where x->>'id'=entry#>>'{aidSupply,prescriptionId}') or not exists(select 1 from jsonb_array_elements(current_sources->'prescriptions') x where x->>'id'=entry#>>'{therapy,prescriptionId}') or not exists(select 1 from jsonb_array_elements(current_sources->'orders') x where x->>'id'=entry#>>'{aidSupply,orderId}') or not exists(select 1 from jsonb_array_elements(current_sources->'orders') x where x->>'id'=entry#>>'{doctorCommunication,medicalOrderId}') then raise exception 'Verordnung oder Anordnungsoriginal fehlt im aktuellen Pflegefall.' using errcode='23514';end if;
 if not exists(select 1 from jsonb_array_elements(current_sources->'serviceRecords') x where x->>'id'=entry#>>'{discharge,firstCareRecordId}') or not exists(select 1 from jsonb_array_elements(current_sources->'careLevels') x where x->>'id'=entry#>>'{benefitChange,careLevelId}') or not exists(select 1 from jsonb_array_elements(current_sources->'tasks') x where x->>'id'=entry#>>'{benefitChange,followUpTaskId}') then raise exception 'Erste Versorgung, Pflegegradfassung oder Folgeauftrag fehlt im aktuellen Pflegefall.' using errcode='23514';end if;
 if not exists(select 1 from jsonb_array_elements(current_sources->'communications') x where x->>'id'=entry#>>'{therapy,communicationId}') or not exists(select 1 from jsonb_array_elements(current_sources->'communications') x where x->>'id'=entry#>>'{doctorCommunication,communicationId}') then raise exception 'Kommunikationsoriginal fehlt im aktuellen Klientenbestand.' using errcode='23514';end if;
 if p_packet->>'action'='create' then if p_packet->'original'<>'null'::jsonb or p_packet->'expectedHeadId'<>'null'::jsonb or (p_packet->>'expectedRevision')::integer<>0 or coalesce(p_packet->>'reason','')<>'' then raise exception 'Neuanlage enthält historischen Kopf.' using errcode='23514';end if;next_root:=next_id;next_revision:=1;else select * into head from public.counseling_coordination_paths v where v.id=(p_packet->>'expectedHeadId')::uuid and v.tenant_id=tenant and v.client_id=client and v.assessment_id=assessment for update;if head.id is null or exists(select 1 from public.counseling_coordination_paths newer where newer.root_id=head.root_id and newer.revision>head.revision) or head.revision<>(p_packet->>'expectedRevision')::integer or care_private.counseling_coordination_original(head.id) is distinct from p_packet->'original' or length(btrim(coalesce(p_packet->>'reason','')))<10 or head.entry=entry then raise exception 'CAS-Kopf, Originalhistorie oder Fortschreibungsgrund wurde verändert.' using errcode='40001';end if;next_root:=head.root_id;next_revision:=head.revision+1;end if;
 fingerprint:='sha256:'||encode(extensions.digest(convert_to(entry::text,'UTF8'),'sha256'),'hex');insert into public.counseling_coordination_paths(id,tenant_id,client_id,assessment_id,root_id,previous_id,revision,status,entry,reason,recorded_by,fingerprint) values(next_id,tenant,client,assessment,next_root,head.id,next_revision,state,entry,coalesce(p_packet->>'reason',''),actor,fingerprint);insert into care_private.counseling_coordination_receipts(tenant_id,request_id,client_id,assessment_id,actor_id,packet,path_id) values(tenant,request,client,assessment,actor,p_packet,next_id);return jsonb_build_object('requestId',request,'packet',p_packet,'original',care_private.counseling_coordination_original(next_id));end$$;
revoke all on function care_private.commit_counseling_coordination_packet(jsonb) from public,anon,authenticated;
create or replace function public.web_commit_counseling_coordination_path_packet(p_packet jsonb) returns jsonb language sql security invoker set search_path='' as $$select care_private.commit_counseling_coordination_packet(p_packet)$$;revoke all on function public.web_commit_counseling_coordination_path_packet(jsonb) from public,anon;grant execute on function public.web_commit_counseling_coordination_path_packet(jsonb) to authenticated;
create or replace function care_private.confirm_counseling_coordination_packet(p_tenant_id uuid,p_client_id uuid,p_assessment_id uuid,p_actor_profile_id uuid,p_request_id uuid,p_packet jsonb) returns jsonb language plpgsql security definer set search_path='' stable as $$declare r care_private.counseling_coordination_receipts%rowtype;begin perform care_private.assert_counseling_coordination_actor(p_tenant_id,p_actor_profile_id,false,false);select * into r from care_private.counseling_coordination_receipts x where x.tenant_id=p_tenant_id and x.request_id=p_request_id;if r.request_id is null or r.client_id<>p_client_id or r.assessment_id<>p_assessment_id or r.actor_id<>p_actor_profile_id or r.packet<>p_packet then return null;end if;return jsonb_build_object('requestId',p_request_id,'packet',r.packet,'original',care_private.counseling_coordination_original(r.path_id));end$$;
revoke all on function care_private.confirm_counseling_coordination_packet(uuid,uuid,uuid,uuid,uuid,jsonb) from public,anon,authenticated;
create or replace function public.web_confirm_counseling_coordination_path_packet(p_tenant_id uuid,p_client_id uuid,p_assessment_id uuid,p_actor_profile_id uuid,p_request_id uuid,p_packet jsonb) returns jsonb language sql security invoker set search_path='' as $$select care_private.confirm_counseling_coordination_packet(p_tenant_id,p_client_id,p_assessment_id,p_actor_profile_id,p_request_id,p_packet)$$;revoke all on function public.web_confirm_counseling_coordination_path_packet(uuid,uuid,uuid,uuid,uuid,jsonb) from public,anon;grant execute on function public.web_confirm_counseling_coordination_path_packet(uuid,uuid,uuid,uuid,uuid,jsonb) to authenticated;
commit;
